"""The `stockroom` command."""

import csv
import datetime
import io
import json
import os
import re
import sys
from typing import Dict, List, NamedTuple, Optional

from . import orders as orders_mod
from . import shelves
from .models import Movement, Order, Quote
from .parsing import ParseError, parse_catalog, parse_date, parse_movements, parse_orders
from .pricing import price_order

CATALOG, MOVEMENTS, ORDERS = "catalog.txt", "movements.txt", "orders.txt"

# command -> (files needed, positional args min, max, options allowed)
COMMANDS = {
    "stock": ((CATALOG, MOVEMENTS), 0, 0, ("json",)),
    "low": ((CATALOG, MOVEMENTS), 0, 0, ("json",)),
    "history": ((CATALOG, MOVEMENTS), 1, 1, ("json",)),
    "receive": ((CATALOG, MOVEMENTS), 3, 4, ()),
    "ship": ((CATALOG, MOVEMENTS), 3, 4, ()),
    "quote": ((CATALOG, ORDERS), 1, 1, ("json",)),
    "fulfil": ((CATALOG, MOVEMENTS, ORDERS), 2, 2, ()),
    "invoice": ((CATALOG, MOVEMENTS, ORDERS), 1, 1, ("json",)),
    "report": ((CATALOG, MOVEMENTS, ORDERS), 0, 0, ("format",)),
}

_SKU = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
_ORDER_ID = re.compile(r"[Ss][Oo]-[0-9]+")
_UINT = re.compile(r"[0-9]+")


class UsageError(Exception):
    """Bad command line -> exit 2."""


class FileProblem(Exception):
    """Unreadable file or directory -> exit 2."""


class Refused(Exception):
    """A data mistake or a refused request -> exit 1."""


class Command(NamedTuple):
    name: str
    args: List[str]
    directory: str
    json: bool
    format: str


def parse_command_line(argv: List[str]) -> Command:
    directory = "."
    rest = []  # type: List[str]
    i = 0
    while i < len(argv):
        token = argv[i]
        if token == "--dir":
            if i + 1 >= len(argv):
                raise UsageError("--dir needs a value")
            directory = argv[i + 1]
            if directory == "":
                raise UsageError("--dir needs a value")
            i += 2
            continue
        if token.startswith("--dir="):
            directory = token[len("--dir="):]
            if directory == "":
                raise UsageError("--dir needs a value")
        else:
            rest.append(token)
        i += 1
    if not rest:
        raise UsageError("no command given")
    name = rest[0]
    if name not in COMMANDS:
        raise UsageError("unknown command %r" % name)
    _files, low, high, options = COMMANDS[name]
    args = []  # type: List[str]
    want_json = False
    fmt = "text"
    tokens = rest[1:]
    free = not options
    j = 0
    options_over = False
    while j < len(tokens):
        token = tokens[j]
        j += 1
        if free or options_over or not token.startswith("-") or token == "-":
            args.append(token)
        elif token == "--":
            options_over = True
        elif token == "--json" and "json" in options:
            want_json = True
        elif "format" in options and (token == "--format" or token.startswith("--format=")):
            if token == "--format":
                if j >= len(tokens):
                    raise UsageError("--format needs a value")
                value = tokens[j]
                j += 1
            else:
                value = token[len("--format="):]
            if value not in ("text", "csv", "json"):
                raise UsageError("bad --format value %r (want text, csv or json)" % value)
            fmt = value
        else:
            raise UsageError("unknown option %r" % token)
    if not low <= len(args) <= high:
        raise UsageError("wrong number of arguments for %s" % name)
    date_arg = {"receive": 0, "ship": 0, "fulfil": 1}.get(name)
    if date_arg is not None:
        try:
            parse_date(args[date_arg], 0)
        except ParseError:
            raise UsageError("bad date %r (want YYYY-MM-DD)" % args[date_arg])
    return Command(name, args, directory, want_json, fmt)


def read_text(directory: str, name: str, required: bool) -> str:
    path = os.path.join(directory, name)
    try:
        with open(path, "rb") as handle:
            data = handle.read()
    except FileNotFoundError:
        if required:
            raise FileProblem("%s: file not found" % name)
        return ""
    except OSError as exc:
        raise FileProblem("%s: %s" % (name, exc.strerror or exc))
    try:
        return data.decode("utf-8-sig")
    except UnicodeDecodeError:
        raise FileProblem("%s: not valid UTF-8" % name)


def parse_file(name: str, parser, *args):
    try:
        return parser(*args)
    except ParseError as exc:
        raise Refused("%s: %s" % (name, exc))


class Data(NamedTuple):
    directory: str
    catalog: dict
    movements: List[Movement]
    orders: List[Order]


def load(cmd: Command) -> Data:
    files = COMMANDS[cmd.name][0]
    if not os.path.isdir(cmd.directory):
        raise FileProblem("%s: not a directory" % cmd.directory)
    texts = {name: read_text(cmd.directory, name, name == CATALOG) for name in files}
    catalog = parse_file(CATALOG, parse_catalog, texts[CATALOG])
    movements = []  # type: List[Movement]
    orders = []  # type: List[Order]
    if MOVEMENTS in texts:
        movements = parse_file(MOVEMENTS, parse_movements, texts[MOVEMENTS], catalog)
    if ORDERS in texts:
        orders = parse_file(ORDERS, parse_orders, texts[ORDERS], catalog)
    return Data(cmd.directory, catalog, movements, orders)


def append_lines(directory: str, name: str, lines: List[str]) -> None:
    path = os.path.join(directory, name)
    prefix = b""
    try:
        with open(path, "rb") as handle:
            handle.seek(0, os.SEEK_END)
            if handle.tell() > 0:
                handle.seek(-1, os.SEEK_END)
                if handle.read(1) != b"\n":
                    prefix = b"\n"
    except FileNotFoundError:
        pass
    except OSError as exc:
        raise FileProblem("%s: %s" % (name, exc.strerror or exc))
    payload = prefix + "".join(line + "\n" for line in lines).encode("utf-8")
    try:
        with open(path, "ab") as handle:
            handle.write(payload)
    except OSError as exc:
        raise FileProblem("%s: %s" % (name, exc.strerror or exc))


# ---------------------------------------------------------------- formatting

def amount(value) -> str:
    return format(value, "f")


def as_json(value) -> str:
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def lookup_sku(text: str, catalog: dict) -> str:
    if _SKU.fullmatch(text) and text.upper() in catalog:
        return text.upper()
    raise Refused("unknown SKU %s" % text)


def lookup_order(text: str, orders: List[Order]) -> Order:
    if _ORDER_ID.fullmatch(text):
        for order in orders:
            if order.id == text.upper():
                return order
    raise Refused("unknown order %s" % text)


def render_quote(order: Order, quote: Quote, as_text: bool, prefix: str = "") -> str:
    if not as_text:
        return as_json({
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "lines": [
                {
                    "sku": l.sku,
                    "quantity": l.quantity,
                    "unit": amount(l.unit),
                    "gross": amount(l.gross),
                    "discount": amount(l.discount),
                    "net": amount(l.net),
                }
                for l in quote.lines
            ],
            "subtotal": amount(quote.subtotal),
            "order_discount": amount(quote.order_discount),
            "tax": amount(quote.tax),
            "total": amount(quote.total),
        })
    out = ["%s%s %s %s" % (prefix, order.id, order.date.isoformat(), order.customer)]
    for l in quote.lines:
        out.append("%s %d %s %s %s %s" % (
            l.sku, l.quantity, amount(l.unit), amount(l.gross), amount(l.discount), amount(l.net)))
    out.append("subtotal " + amount(quote.subtotal))
    out.append("order discount " + amount(quote.order_discount))
    out.append("tax " + amount(quote.tax))
    out.append("total " + amount(quote.total))
    return "\n".join(out) + "\n"


# ------------------------------------------------------------------ commands

def do_stock(cmd: Command, data: Data) -> str:
    levels = shelves.stock_levels(data.catalog, data.movements)
    rows = [(sku, data.catalog[sku], levels[sku]) for sku in sorted(data.catalog)]
    if cmd.json:
        return as_json([
            {"sku": sku, "name": p.name, "onhand": n, "status": shelves.status(p, n)}
            for sku, p, n in rows])
    return "".join("%s %d %s %s\n" % (sku, n, shelves.status(p, n), p.name) for sku, p, n in rows)


def do_low(cmd: Command, data: Data) -> str:
    levels = shelves.stock_levels(data.catalog, data.movements)
    rows = [
        (sku, levels[sku], data.catalog[sku].reorder, shelves.buy_quantity(data.catalog[sku], levels[sku]))
        for sku in sorted(data.catalog)
        if shelves.status(data.catalog[sku], levels[sku]) != "ok"
    ]
    if cmd.json:
        return as_json([
            {"sku": s, "onhand": n, "reorder": r, "buy": b} for s, n, r, b in rows])
    return "".join("%s %d %d %d\n" % row for row in rows)


def do_history(cmd: Command, data: Data) -> str:
    sku = lookup_sku(cmd.args[0], data.catalog)
    rows = shelves.history(data.movements, sku)
    if cmd.json:
        return as_json([
            {"date": m.date.isoformat(), "delta": "%+d" % m.quantity, "balance": b, "note": m.note}
            for m, b in rows])
    return "".join(
        "%s %+d %d%s\n" % (m.date.isoformat(), m.quantity, b, " " + m.note if m.note else "")
        for m, b in rows)


def do_move(cmd: Command, data: Data) -> str:
    date_text, sku_text, qty_text = cmd.args[:3]
    note = cmd.args[3] if len(cmd.args) == 4 else ""
    sku = lookup_sku(sku_text, data.catalog)
    if not _UINT.fullmatch(qty_text):
        raise Refused("bad quantity %r (want a whole number of 1 or more)" % qty_text)
    try:
        qty = int(qty_text)
    except ValueError:
        raise Refused("quantity is too large")
    if qty < 1:
        raise Refused("bad quantity %r (want a whole number of 1 or more)" % qty_text)
    if "\n" in note or "\r" in note:
        raise Refused("a note may not contain a line break")
    note = note.strip()
    try:
        note.encode("utf-8")
    except UnicodeEncodeError:
        raise Refused("note is not valid text")
    delta = qty if cmd.name == "receive" else -qty
    date = datetime.date.fromisoformat(date_text)
    if shelves.would_go_negative(data.movements, Movement(date, sku, delta, note)):
        raise Refused("stock of %s would go below zero" % sku)
    line = "%s %s %+d%s" % (date_text, sku, delta, " " + note if note else "")
    append_lines(data.directory, MOVEMENTS, [line])
    return line + "\n"


def do_quote(cmd: Command, data: Data) -> str:
    order = lookup_order(cmd.args[0], data.orders)
    return render_quote(order, price_order(order, data.catalog), not cmd.json)


def do_fulfil(cmd: Command, data: Data) -> str:
    order = lookup_order(cmd.args[0], data.orders)
    date = datetime.date.fromisoformat(cmd.args[1])
    if date < order.date:
        raise Refused("%s is dated %s; cannot fulfil on %s" % (order.id, order.date.isoformat(), cmd.args[1]))
    shipped = orders_mod.shipped_so_far(order, data.movements)
    plan = orders_mod.plan_shipment(order, date, data.movements)
    new_lines = ["%s %s -%d order %s" % (cmd.args[1], sku, n, order.id) for sku, n in plan if n > 0]
    if new_lines:
        append_lines(data.directory, MOVEMENTS, new_lines)
    after = {sku: shipped[sku] + n for sku, n in plan}
    out = []
    for sku, qty in order.lines:
        out.append("%s shipped %d backordered %d" % (sku, dict(plan)[sku], qty - after[sku]))
    out.append("status " + orders_mod.order_status(order, after))
    return "\n".join(out) + "\n"


def do_invoice(cmd: Command, data: Data) -> str:
    order = lookup_order(cmd.args[0], data.orders)
    shipped = orders_mod.shipped_so_far(order, data.movements)
    sent = orders_mod.shipped_order(order, shipped)
    if not sent.lines:
        raise Refused("nothing shipped for %s" % order.id)
    return render_quote(sent, price_order(sent, data.catalog), not cmd.json, "invoice ")


def do_report(cmd: Command, data: Data) -> str:
    rows = []
    for order in sorted(data.orders, key=lambda o: (o.date, o.id)):
        shipped = orders_mod.shipped_so_far(order, data.movements)
        sent = orders_mod.shipped_order(order, shipped)
        invoiced = price_order(sent, data.catalog).total if sent.lines else None
        rows.append({
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "status": orders_mod.order_status(order, shipped),
            "ordered": sum(q for _, q in order.lines),
            "shipped": sum(shipped.values()),
            "quoted": amount(price_order(order, data.catalog).total),
            "invoiced": amount(invoiced) if invoiced is not None else "0.00",
        })
    if cmd.format == "json":
        return as_json(rows)
    if cmd.format == "csv":
        buffer = io.StringIO()
        writer = csv.writer(buffer, lineterminator="\n")
        keys = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]
        writer.writerow(keys)
        for row in rows:
            writer.writerow([row[k] for k in keys])
        return buffer.getvalue()
    return "".join(
        "%s %s %s %s %d/%d %s %s\n" % (
            r["order"], r["date"], r["customer"], r["status"],
            r["shipped"], r["ordered"], r["quoted"], r["invoiced"])
        for r in rows)


HANDLERS = {
    "stock": do_stock,
    "low": do_low,
    "history": do_history,
    "receive": do_move,
    "ship": do_move,
    "quote": do_quote,
    "fulfil": do_fulfil,
    "invoice": do_invoice,
    "report": do_report,
}


# ---------------------------------------------------------------------- main

def emit(text: str) -> int:
    """Write stdout as UTF-8; a closed pipe ends quietly with status 0."""
    try:
        buffer = getattr(sys.stdout, "buffer", None)
        if buffer is not None:
            sys.stdout.flush()
            buffer.write(text.encode("utf-8"))
            buffer.flush()
        else:
            sys.stdout.write(text)
            sys.stdout.flush()
    except BrokenPipeError:
        silence_stdout()
        return 0
    except OSError as exc:
        silence_stdout()
        fail("cannot write output: %s" % (exc.strerror or exc))
        return 2
    return 0


def silence_stdout() -> None:
    """Point stdout at /dev/null so the exit-time flush cannot fail noisily."""
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def fail(message: str) -> None:
    try:
        sys.stderr.write("stockroom: %s\n" % message)
        sys.stderr.flush()
    except (OSError, ValueError):
        pass


def main(argv: Optional[List[str]] = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    try:
        cmd = parse_command_line(args)
        data = load(cmd)
        output = HANDLERS[cmd.name](cmd, data)
    except UsageError as exc:
        fail(str(exc))
        return 2
    except FileProblem as exc:
        fail(str(exc))
        return 2
    except Refused as exc:
        fail(str(exc))
        return 1
    return emit(output)

